import Link from "next/link";
import { AdminFilterPanel } from "@/components/admin/admin-filter-panel";
import { AdminNav } from "@/components/admin/admin-nav";
import { requireAdmin } from "@/lib/admin/authorization";
import { getAdminOverview } from "@/lib/admin/service";
import { getRetentionDiagnostics, listAdminUsersWithActivity } from "@/lib/admin/user-activity";
import { learnerActivityStateLabel, getLearnerActivityState, userActivityActionLabel } from "@/lib/admin/user-activity-policy";
import { getPreferences } from "@/lib/i18n/get-translations";

type Query = { q?: string; plan?: string; status?: string; role?: string; verified?: string; activity?: string; learning?: string; sort?: string; page?: string };
const date = (value: Date | null, locale: string, withTime = false) => value ? new Intl.DateTimeFormat(locale, { timeZone: "Asia/Ho_Chi_Minh", day: "2-digit", month: "2-digit", year: "numeric", ...(withTime ? { hour: "2-digit", minute: "2-digit" } : {}) }).format(value) : "—";
const statusLabel = (status: string, vi: boolean) => status === "active" ? (vi ? "Đang hoạt động" : "Active") : status === "disabled" ? (vi ? "Tạm khóa" : "Suspended") : (vi ? "Chờ xác minh" : "Pending verification");
const tone = (status: string) => status === "active" ? "bg-emerald-50 text-emerald-800" : status === "disabled" ? "bg-red-50 text-red-800" : "bg-amber-50 text-amber-800";
const planLabel = (plan: string, vi: boolean) => plan === "PREMIUM" ? "Premium" : plan === "EXPIRED" ? (vi ? "Đã hết hạn" : "Expired") : "Free";
const goalLabel = (goal: { targetScore: number | null; examDate: string | null } | null, vi: boolean) => goal ? [goal.targetScore ? `TOEIC ${goal.targetScore}` : null, goal.examDate ? `${vi ? "Thi" : "Exam"} ${goal.examDate}` : null].filter(Boolean).join(" · ") || "—" : "—";

export default async function UsersPage({ searchParams }: { searchParams: Promise<Query> }) {
  const actor = await requireAdmin("USER_READ"); const [prefs, query, overview, retention] = await Promise.all([getPreferences(actor.id), searchParams, getAdminOverview(), getRetentionDiagnostics()]); const vi = prefs.interfaceLanguage === "vi"; const locale = vi ? "vi-VN" : "en-US";
  const page = Math.max(1, Number.parseInt(query.page ?? "1") || 1); const data = await listAdminUsersWithActivity({ search: query.q, plan: query.plan, status: query.status, role: query.role, verified: query.verified, activity: query.activity, learning: query.learning, sort: query.sort, page }); const pages = Math.ceil(data.total / data.pageSize);
  const href = (nextPage: number) => { const p = new URLSearchParams(); Object.entries(query).forEach(([k,v]) => { if (v && k !== "page") p.set(k,v); }); p.set("page", String(nextPage)); return `?${p}`; };
  const activeFilterCount = [query.q, query.plan, query.status, query.role, query.verified, query.activity, query.learning, query.sort].filter(Boolean).length; const hasFilters = activeFilterCount > 0; const select = "mt-1 min-h-11 w-full rounded-xl border border-slate-300 bg-white px-3 text-sm";
  return <main className="min-h-screen bg-slate-50 px-4 py-6 text-slate-900 sm:px-6"><div className="mx-auto max-w-7xl"><AdminNav locale={prefs.interfaceLanguage}/>
    <header className="mt-8"><p className="text-xs font-black uppercase tracking-[.18em] text-teal-700">{vi?"Vận hành & hỗ trợ":"Operations & support"}</p><h1 className="mt-2 text-3xl font-black">{vi?"Người dùng":"Users"}</h1><p className="mt-2 text-slate-600">{vi?"Quản lý tài khoản, quyền truy cập và trạng thái học tập.":"Manage accounts, access, and learning status."}</p></header>
    <section aria-label={vi?"Tổng quan người dùng":"User overview"} className="mt-6 grid gap-3 sm:grid-cols-2 lg:grid-cols-4">{[[vi?"Tổng người dùng":"Total users",overview.total],["Premium",overview.premium],[vi?"Đã tạm khóa":"Suspended",overview.suspended],[vi?"Chưa xác minh":"Unverified",overview.unverified]].map(([label,value])=><article className="rounded-2xl border border-slate-200 bg-white p-4" key={label}><p className="text-sm text-slate-500">{label}</p><p className="mt-1 text-2xl font-black">{value}</p></article>)}</section>
    <section aria-label={vi?"Chẩn đoán retention":"Retention diagnostics"} className="admin-retention mt-4 overflow-hidden border p-5 sm:p-6"><div className="flex flex-wrap items-end justify-between gap-4"><div><p className="text-xs font-black uppercase tracking-[.18em] text-teal-300">Retention · 7 {vi?"ngày sản phẩm":"product days"}</p><h2 className="mt-2 text-2xl font-black">{vi?"Người học quay lại ít nhất 2 ngày":"Learners returning on 2+ days"}</h2><p className="mt-2 text-sm text-slate-300">{vi?"Chỉ tính Practice, Bài hôm nay và ôn câu sai đã nộp, có câu trả lời thật.":"Submitted Practice, Workout, and mistake review with real answers only."}</p></div><div className="text-left sm:text-right"><p className="text-4xl font-black text-teal-300">{retention.returned2Days7d} / {retention.totalLearners}</p><p className="mt-1 text-xs text-slate-400">{retention.totalLearners<20?(vi?"Mẫu nhỏ; ưu tiên số lượng tuyệt đối.":"Small sample; prioritize counts."):(vi?"Tổng người học đã đăng ký":"Total registered learners")}</p></div></div><div className="mt-5 grid gap-2 sm:grid-cols-2 lg:grid-cols-5">{[[vi?"Đăng ký 7 ngày":"7-day signups",retention.signups7d],[vi?"Đã kích hoạt":"Activated",retention.activated],[vi?"Học đúng 1 ngày":"Exactly 1 day",retention.oneLearningDay7d],[vi?"Học 3+ ngày":"3+ days",retention.returned3Days7d],[vi?"Chưa học":"No learning yet",retention.noMeaningfulLearning]].map(([label,value])=><div className="rounded-xl border border-white/10 bg-white/5 p-3" key={String(label)}><p className="text-xs text-slate-400">{label}</p><strong className="mt-1 block text-xl">{value}</strong></div>)}</div></section>
    <AdminFilterPanel activeCount={activeFilterCount} clearHref="/admin/users" clearLabel={vi?"Xóa bộ lọc":"Clear filters"} label={vi?"Bộ lọc":"Filters"}><form className="rounded-2xl border border-slate-200 bg-white p-4" method="get"><div className="grid gap-3 md:grid-cols-2 xl:grid-cols-4"><div className="xl:col-span-2"><label className="text-sm font-bold" htmlFor="user-search">{vi?"Tìm kiếm":"Search"}</label><input className="mt-1 min-h-11 w-full rounded-xl border border-slate-300 px-4" defaultValue={query.q} id="user-search" name="q" placeholder={vi?"Tìm theo email hoặc tên":"Search by email or name"}/></div>
      <label className="text-sm font-bold">{vi?"Gói":"Plan"}<select className={select} defaultValue={query.plan??""} name="plan"><option value="">{vi?"Tất cả":"All"}</option><option value="free">Free</option><option value="premium">Premium</option></select></label>
      <label className="text-sm font-bold">{vi?"Trạng thái":"Status"}<select className={select} defaultValue={query.status??""} name="status"><option value="">{vi?"Tất cả":"All"}</option><option value="active">{vi?"Đang hoạt động":"Active"}</option><option value="disabled">{vi?"Tạm khóa":"Suspended"}</option><option value="pending_verification">{vi?"Chờ xác minh":"Pending verification"}</option></select></label>
      <label className="text-sm font-bold">{vi?"Vai trò":"Role"}<select className={select} defaultValue={query.role??""} name="role"><option value="">{vi?"Tất cả":"All"}</option><option value="learner">Learner</option><option value="admin">Admin</option></select></label>
      <label className="text-sm font-bold">{vi?"Xác minh email":"Email verification"}<select className={select} defaultValue={query.verified??""} name="verified"><option value="">{vi?"Tất cả":"All"}</option><option value="yes">{vi?"Đã xác minh":"Verified"}</option><option value="no">{vi?"Chưa xác minh":"Unverified"}</option></select></label>
      <label className="text-sm font-bold">{vi?"Hoạt động":"Activity"}<select className={select} defaultValue={query.activity??""} name="activity"><option value="">{vi?"Tất cả":"All"}</option><option value="recent">{vi?"Đăng nhập trong 30 ngày":"Logged in within 30 days"}</option><option value="never">{vi?"Chưa từng đăng nhập":"Never logged in"}</option></select></label>
      <label className="text-sm font-bold">{vi?"Retention":"Retention"}<select className={select} defaultValue={query.learning??""} name="learning"><option value="">{vi?"Tất cả":"All"}</option><option value="none">{vi?"Chưa học":"No learning yet"}</option><option value="one">{vi?"Học 1 ngày":"1 learning day"}</option><option value="returning">{vi?"Học 2+ ngày":"2+ learning days"}</option><option value="habit">{vi?"Học 3+ ngày":"3+ learning days"}</option></select></label>
      <label className="text-sm font-bold">{vi?"Sắp xếp":"Sort"}<select className={select} defaultValue={query.sort??"created"} name="sort"><option value="created">{vi?"Mới tham gia":"Newest joined"}</option><option value="created_asc">{vi?"Tham gia lâu nhất":"Oldest joined"}</option><option value="learning_recent">{vi?"Học gần đây":"Recent learning"}</option><option value="learning_oldest">{vi?"Lâu chưa học":"Least recent learning"}</option><option value="login">{vi?"Đăng nhập gần nhất":"Last login"}</option><option value="identity">Email A–Z</option></select></label></div><div className="mt-4 flex flex-wrap gap-3"><button className="min-h-11 rounded-xl bg-slate-900 px-5 font-bold text-white">{vi?"Áp dụng":"Apply"}</button></div></form></AdminFilterPanel>
    {data.rows.length ? <><div className="mt-5 grid gap-3 md:hidden">{data.rows.map(user=>{const lifecycle=getLearnerActivityState({learningDays:user.learningDays,lastLearningAt:user.lastLearningAt});return <article className="rounded-2xl border border-slate-200 bg-white p-4" key={user.id}><div className="flex items-start justify-between gap-3"><div className="min-w-0"><Link className="font-black text-teal-800" href={`/admin/users/${user.id}`}>{user.name??(vi?"Chưa đặt tên":"Unnamed user")}</Link><p className="mt-1 truncate text-sm text-slate-500">{user.email}</p></div><span className="rounded-full bg-slate-100 px-2 py-1 text-xs font-black">{planLabel(user.plan,vi)}</span></div><div className="mt-4 grid grid-cols-3 gap-2 text-sm"><div><span className="text-slate-500">{vi?"Ngày học":"Days"}</span><strong className="block">{user.learningDays}</strong></div><div><span className="text-slate-500">{vi?"Buổi":"Sessions"}</span><strong className="block">{user.sessions}</strong></div><div><span className="text-slate-500">{vi?"Câu":"Questions"}</span><strong className="block">{user.questions}</strong></div></div><p className="mt-3 text-sm"><span className="font-bold">{learnerActivityStateLabel(lifecycle,vi)}</span> · {user.lastLearningAt?date(user.lastLearningAt,locale,true):(vi?"Chưa có lần học":"No learning yet")}</p><p className="mt-2 text-sm text-slate-600">{user.lastAction?userActivityActionLabel(user.lastAction.action,vi):(vi?"Tạo tài khoản":"Account created")}</p></article>})}</div><div className="mt-5 hidden overflow-x-auto rounded-2xl border border-slate-200 bg-white md:block"><table className="w-full min-w-[1180px] text-left text-sm"><thead className="bg-slate-100"><tr>{[vi?"Người dùng":"User",vi?"Tham gia":"Joined",vi?"Học gần nhất":"Last learning",vi?"Ngày học":"Learning days",vi?"Buổi / câu":"Sessions / questions",vi?"Hành động gần nhất":"Last meaningful action",vi?"Mục tiêu":"Goal",vi?"Gói":"Plan"].map(x=><th className="p-4" scope="col" key={x}>{x}</th>)}</tr></thead><tbody>{data.rows.map(user=>{const lifecycle=getLearnerActivityState({learningDays:user.learningDays,lastLearningAt:user.lastLearningAt});return <tr className="border-t border-slate-100 align-top hover:bg-slate-50" key={user.id}><td className="p-4"><Link className="font-bold text-teal-800 underline-offset-2 hover:underline" href={`/admin/users/${user.id}`}>{user.name??(vi?"Chưa đặt tên":"Unnamed user")}</Link><p className="mt-1 max-w-[16rem] truncate text-slate-500">{user.email}</p><div className="mt-2 flex flex-wrap gap-1"><span className={`rounded-full px-2 py-1 text-xs font-bold ${tone(user.status)}`}>{statusLabel(user.status,vi)}</span><span className="rounded-full bg-slate-100 px-2 py-1 text-xs font-bold">{user.admin?"Admin":"Learner"}</span>{actor.id===user.id?<span className="rounded-full bg-blue-50 px-2 py-1 text-xs font-bold text-blue-800">{vi?"Bạn":"You"}</span>:null}</div></td><td className="whitespace-nowrap p-4">{date(user.createdAt,locale)}</td><td className="p-4"><span className="whitespace-nowrap">{date(user.lastLearningAt,locale,true)}</span><p className="mt-1 text-xs font-bold text-slate-500">{learnerActivityStateLabel(lifecycle,vi)}</p></td><td className="p-4 text-center font-black">{user.learningDays}</td><td className="p-4 whitespace-nowrap">{user.sessions} / {user.questions}</td><td className="p-4"><strong>{user.lastAction?userActivityActionLabel(user.lastAction.action,vi):(vi?"Tạo tài khoản":"Account created")}</strong><p className="mt-1 whitespace-nowrap text-xs text-slate-500">{date(user.lastAction?.occurredAt??user.createdAt,locale,true)}</p></td><td className="p-4">{goalLabel(user.goal,vi)}</td><td className="p-4"><span className={`rounded-full px-3 py-1 text-xs font-bold ${user.plan==="PREMIUM"?"bg-teal-50 text-teal-800":"bg-slate-100 text-slate-700"}`}>{planLabel(user.plan,vi)}</span></td></tr>})}</tbody></table></div></> : <section className="mt-5 rounded-2xl border border-dashed bg-white p-10 text-center"><h2 className="text-xl font-black">{hasFilters?(vi?"Không tìm thấy người dùng phù hợp.":"No matching users."):(vi?"Chưa có người dùng.":"No users yet.")}</h2><p className="mt-2 text-slate-600">{hasFilters?(vi?"Thử tên, email khác hoặc xóa bộ lọc.":"Try another name or email, or clear the filters."):(vi?"Tài khoản sẽ xuất hiện tại đây khi được tạo.":"Accounts will appear here once created.")}</p>{hasFilters?<Link className="mt-5 inline-flex rounded-xl bg-slate-900 px-5 py-3 font-bold text-white" href="/admin/users">{vi?"Xóa bộ lọc":"Clear filters"}</Link>:null}</section>}
    {data.total>0&&pages>1?<nav aria-label={vi?"Phân trang người dùng":"User pages"} className="mt-5 flex items-center justify-between"><Link aria-disabled={page<=1} className={`rounded-lg border bg-white px-4 py-2 font-semibold ${page<=1?"pointer-events-none opacity-40":""}`} href={href(page-1)}>{vi?"Trước":"Previous"}</Link><span>{page} / {pages}</span><Link aria-disabled={page>=pages} className={`rounded-lg border bg-white px-4 py-2 font-semibold ${page>=pages?"pointer-events-none opacity-40":""}`} href={href(page+1)}>{vi?"Sau":"Next"}</Link></nav>:null}
  </div></main>;
}
